let dateCounter = 0;
/** A new valid date on every call, so bookings of different tests never overlap. */
export function nextDate() {
  dateCounter += 1;
  return new Date(Date.UTC(2030, 0, 1 + dateCounter)).toISOString().slice(0, 10);
}

