export function createFakeFetch(log = []) {
  const calls = [];
  const fetch = (...args) => {
    const call = { url: args[0], options: args[1], argCount: args.length, jsonCalls: 0, settled: false };
    calls.push(call);
    log.push(['fetch', args[0]]);
    return new Promise((resolve, reject) => {
      call.resolve = resolve;
      call.reject = reject;
    });
  };
  const settle = (call, fn) => {
    call.settled = true;
    fn();
  };
  return {
    fetch,
    calls,
    get pending() { return calls.filter((c) => !c.settled); },
    nextCall: () => calls.find((c) => !c.seen && (c.seen = true)),
    respond(call, status, body) {
      settle(call, () => call.resolve({
        status,
        json: () => { call.jsonCalls += 1; return Promise.resolve(body); }
      }));
    },
    respondRaw(call, status, jsonImpl) {
      settle(call, () => call.resolve({
        status,
        json: () => { call.jsonCalls += 1; return jsonImpl(); }
      }));
    },
    fail(call) {
      settle(call, () => call.reject(new TypeError('fetch failed')));
    }
  };
}

