async function startServerOn3000(t, value, cwd) {
  const { spawn } = await import('node:child_process');
  const env = { ...process.env, ...(value === undefined ? {} : { PORT: value }) };
  if (value === undefined) delete env.PORT;
  delete env.DATA_FILE;
  const child = spawn(process.execPath, [path.join(ROOT, 'server.mjs')], { cwd, env, stdio: ['ignore', 'pipe', 'pipe'] });
  const closed = new Promise((resolve) => child.on('close', resolve));
  t.after(async () => { child.kill('SIGKILL'); await closed; });
  let stdout = '';
  child.stdout.setEncoding('utf8').on('data', (d) => { stdout += d; });
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('no listening line')), 5000);
    child.stdout.on('data', () => { if (stdout.endsWith('\n')) { clearTimeout(timer); resolve(); } });
    child.on('exit', () => { clearTimeout(timer); resolve(); });
  });
  return { stdout };
}

